import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"前端面试冲刺计划（3 周）","description":"","frontmatter":{},"headers":[],"relativePath":"blog/frontend-interview-3w.md","filePath":"blog/frontend-interview-3w.md"}'),i={name:"blog/frontend-interview-3w.md"};function h(l,t,o,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="前端面试冲刺计划-3-周" tabindex="-1">前端面试冲刺计划（3 周） <a class="header-anchor" href="#前端面试冲刺计划-3-周" aria-label="Permalink to &quot;前端面试冲刺计划（3 周）&quot;">​</a></h1><blockquote><p>目标：面试冲刺 · React + Vue 双深 · 按面试频率排优先级<br> 方法：周主题（方案 1）+ 笔记驱动费曼闭环（方案 3）<br> 节奏：每天约 2.5–3 小时</p></blockquote><p>配套错题可回填各篇文末 <code>## 面试卡点</code>，或集中记在 <a href="./interview-mistakes.html">interview-mistakes</a>。</p><hr><h2 id="每日闭环" tabindex="-1">每日闭环 <a class="header-anchor" href="#每日闭环" aria-label="Permalink to &quot;每日闭环&quot;">​</a></h2><ol><li><strong>读笔记</strong>（25–40min）— 只过下表对应 md，不另开新坑</li><li><strong>费曼口述</strong>（15–20min）— 录音：是什么 → 为什么 → 怎么实现 → 一道追问</li><li><strong>默写 / 代码</strong>（40–60min）— 不看笔记写一遍</li><li><strong>回填</strong>（10min）— 卡点一句话写回笔记或错题本</li></ol><h3 id="硬规则" tabindex="-1">硬规则 <a class="header-anchor" href="#硬规则" aria-label="Permalink to &quot;硬规则&quot;">​</a></h3><ul><li>每天最多 <strong>1 个新主题深度</strong> + <strong>1 个复习旧点</strong></li><li>W1–W2 每天算法最多 <strong>1 题</strong>（20–30min）；W3 再加量</li><li>周末 / 复盘日：错题本 + 口述总复习，<strong>不学新大块</strong></li><li>AI / Node / 小程序 / Hybrid <strong>不进主线</strong>（JD 点名再临时补）</li></ul><hr><h2 id="三周总览" tabindex="-1">三周总览 <a class="header-anchor" href="#三周总览" aria-label="Permalink to &quot;三周总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周</th><th>主题</th><th>目标</th></tr></thead><tbody><tr><td>W1</td><td>JS 基础 + 手写 + 浏览器</td><td>高频手写能默写；事件循环 / 渲染 / 缓存能讲清</td></tr><tr><td>W2</td><td>Vue + React（深）</td><td>两边原理各能口述约 10 分钟；对比题不慌</td></tr><tr><td>W3</td><td>工程化 + 精简算法 + 模拟面</td><td>性能 / SSR 故事能串；过 2–3 场模拟</td></tr></tbody></table><hr><h2 id="w1-·-js-手写-浏览器" tabindex="-1">W1 · JS + 手写 + 浏览器 <a class="header-anchor" href="#w1-·-js-手写-浏览器" aria-label="Permalink to &quot;W1 · JS + 手写 + 浏览器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天</th><th>主题</th><th>笔记</th><th>当天产出</th></tr></thead><tbody><tr><td>D1</td><td>类型 / 闭包 / this</td><td><a href="/basis/other/arrowFunction.html">arrowFunction</a>、<a href="/react/closure.html">closure</a></td><td>口述闭包 3 场景</td></tr><tr><td>D2</td><td>原型 / 继承 / new</td><td><a href="/basis/write/new.html">new</a>、<a href="/basis/write/inherit.html">inherit</a>、<a href="/basis/write/instanceof.html">instanceof</a>、<a href="/basis/write/object-create.html">object-create</a></td><td>默写 <code>new</code>、<code>instanceof</code>、寄生组合继承骨架</td></tr><tr><td>D3</td><td>Promise / async</td><td><a href="/basis/write/promise.html">promise</a>、<a href="/basis/write/promise-simple.html">promise-simple</a>、<a href="/basis/write/async.html">async</a></td><td>默写简易 Promise；讲清微任务</td></tr><tr><td>D4</td><td>高频手写包</td><td><a href="/basis/write/call-apply-bind.html">call-apply-bind</a>、<a href="/basis/write/debounce-throttle.html">debounce-throttle</a>、<a href="/basis/write/deepCopy.html">deepCopy</a>、<a href="/basis/write/eventBus.html">eventBus</a>、<a href="/basis/write/currying.html">currying</a></td><td>5 个里至少默写对 3 个，其余周末补</td></tr><tr><td>D5</td><td>事件循环 + JS 执行</td><td><a href="/browser/eventLoop.html">eventLoop</a>、<a href="/browser/jsRun.html">jsRun</a></td><td>口述一道经典输出题 + 宏/微任务判定</td></tr><tr><td>D6</td><td>渲染 / 缓存 / 网络</td><td><a href="/browser/render-process.html">render-process</a>、<a href="/browser/cache.html">cache</a>、<a href="/browser/http.html">http</a>（可选 <a href="/browser/dns.html">dns</a>、<a href="/browser/tcp.html">tcp</a>）</td><td>讲清 URL → 首屏；强缓 vs 协商缓</td></tr><tr><td>D7</td><td>W1 复盘</td><td>错题本 + D1–D6</td><td>补齐 D4 未过手写；1 道综合口述录音</td></tr></tbody></table><p><strong>W1 算法（每天 1 题）</strong>：优先 <a href="/algorithm/array/one.html">array</a>、<a href="/algorithm/string/one.html">string</a>、<a href="/algorithm/stack/base.html">stack</a>；先不做深 DP。</p><p><strong>W1 过关</strong>：手写 <code>new</code> / Promise / call-apply-bind / 防抖节流 / 深拷贝；口述事件循环、渲染流水线、HTTP 缓存各 ≥5 分钟。</p><hr><h2 id="w2-·-vue-react-双深" tabindex="-1">W2 · Vue + React 双深 <a class="header-anchor" href="#w2-·-vue-react-双深" aria-label="Permalink to &quot;W2 · Vue + React 双深&quot;">​</a></h2><p>原则：<strong>一天只深挖一边</strong>，另一边最多 15min 对比复习。</p><table tabindex="0"><thead><tr><th>天</th><th>主线</th><th>笔记</th><th>当天产出</th></tr></thead><tbody><tr><td>D8</td><td>Vue 响应式</td><td><a href="/vue/reactive/ref&amp;reactive.html">ref&amp;reactive</a>、<a href="/vue/reactive/vue-array.html">vue-array</a>、<a href="/vue/reactive/vue2-get-watcher.html">vue2-get-watcher</a>、<a href="/vue/reactive/watch&amp;computed.html">watch&amp;computed</a>、<a href="/vue/other/watch&amp;watchEffect.html">watch&amp;watchEffect</a></td><td>口述 Vue2 vs Vue3 响应式；能画依赖收集图</td></tr><tr><td>D9</td><td>Vue 更新 / Diff / 调度</td><td><a href="/vue/reactive/dom-diff.html">dom-diff</a>、<a href="/vue/other/nextTick.html">nextTick</a>、<a href="/vue/init/render-process.html">render-process</a>、<a href="/vue/init/init.html">init</a></td><td>讲清更新链路；<code>nextTick</code> 要点</td></tr><tr><td>D10</td><td>Vue 周边高频</td><td><a href="/vue/other/keep-alive.html">keep-alive</a>、<a href="/vue/other/template.html">template</a>、<a href="/vue/other/v2&amp;v3.html">v2&amp;v3</a>、<a href="/vue/other/design-mode.html">design-mode</a>、<a href="/vue/global/vue-extend.html">vue-extend</a></td><td>keep-alive / 编译大致流程；3 道对比追问</td></tr><tr><td>D11</td><td>React 核心</td><td><a href="/react/useState.html">useState</a>、<a href="/react/ref.html">ref</a>、<a href="/react/生命周期.html">生命周期</a>、<a href="/react/合成事件.html">合成事件</a>、<a href="/react/hoc.html">hoc</a></td><td>Hooks 规则 + 合成事件；re-render 触发点</td></tr><tr><td>D12</td><td>React Fiber / 调度</td><td><a href="/react/fiber.html">fiber</a>、<a href="/react/双缓存机制.html">双缓存机制</a>、<a href="/react/updateProgress.html">updateProgress</a>、<a href="/react/messageChannel.html">messageChannel</a>、<a href="/react/Didact.html">Didact</a>（可选）</td><td>Fiber 为何存在、双缓存、时间切片直觉</td></tr><tr><td>D13</td><td>React 生态 + 对比</td><td><a href="/react/redux.html">redux</a>、<a href="/react/react-router.html">react-router</a>、<a href="/react/react-vs-vue.html">react-vs-vue</a>、<a href="/react/closure.html">closure</a></td><td>「Vue vs React」10 分钟对比稿（录音）</td></tr><tr><td>D14</td><td>W2 复盘</td><td>D8–D13 错题 + 双边口述</td><td>各录一段 8–10min 框架原理</td></tr></tbody></table><p><strong>W2 算法（每天 ≤1 题）</strong>：优先 <a href="/algorithm/tree/base.html">tree</a>、<a href="/algorithm/linkedList/one.html">linkedList</a>、<a href="/algorithm/recursion/base.html">recursion</a>。</p><p><strong>W2 过关</strong>：Vue 响应式 / Diff / nextTick；React Hooks / Fiber·双缓存 / 合成事件；一份「同题双答」对比清单。</p><hr><h2 id="w3-·-工程化-精简算法-模拟面" tabindex="-1">W3 · 工程化 + 精简算法 + 模拟面 <a class="header-anchor" href="#w3-·-工程化-精简算法-模拟面" aria-label="Permalink to &quot;W3 · 工程化 + 精简算法 + 模拟面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天</th><th>主题</th><th>笔记</th><th>当天产出</th></tr></thead><tbody><tr><td>D15</td><td>构建 / 优化</td><td><a href="/build-tool/webpack/init.html">webpack init</a>、<a href="/build-tool/webpack/loader.html">loader</a>、<a href="/build-tool/webpack/plugin.html">plugin</a>、<a href="/build-tool/webpack/treeShaking.html">treeShaking</a>、<a href="/build-tool/webpack/optimize.html">optimize</a>、<a href="/build-tool/webpack/speed.html">speed</a>、<a href="/build-tool/webpack/size.html">size</a></td><td>构建链路 + 3 个优化手段（体积 / 速度 / 缓存）</td></tr><tr><td>D16</td><td>性能 / Web Vitals / 安全</td><td><a href="/browser/web-vitals.html">web-vitals</a>、<a href="/browser/security.html">security</a>、<a href="/browser/heuristicCaching.html">heuristicCaching</a>（可选）</td><td>1 个性能案例（指标 → 手段 → 结果）；XSS / CSRF</td></tr><tr><td>D17</td><td>SSR / Next</td><td><a href="/basis/ssr/ssr原理.html">ssr原理</a>、<a href="/basis/ssr/手写vue-ssr.html">手写vue-ssr</a>、<a href="/nextjs/nextjs.html">nextjs</a>、<a href="/nextjs/ssr与ssg.html">ssr与ssg</a></td><td>CSR vs SSR vs SSG；首屏与 SEO 取舍</td></tr><tr><td>D18</td><td>算法精简包 A</td><td>array / string / stack / linkedList 错题</td><td><strong>3 题</strong>；思路 + 复杂度</td></tr><tr><td>D19</td><td>算法精简包 B</td><td>tree / heap / dynamic（只做已写过的，不扩新类型）</td><td>再 <strong>3 题</strong>；DP 只保 1–2 道熟题</td></tr><tr><td>D20</td><td>模拟面试 #1</td><td>JS + 浏览器 + 主框架（Vue 或 React 当天主答）</td><td>45–60min；录音；整理 Top5 卡点</td></tr><tr><td>D21</td><td>模拟 #2 + 总复盘</td><td>换另一边框架 + 工程化追问；三周错题</td><td>第二场模拟；输出上场清单（手写 8 + 口述 12）</td></tr></tbody></table><p><strong>W3 规则</strong>：D15–D17 算法热身可选每天 1 题；加量在 D18–D19。模拟必须录音；卡 &gt;30s 的点回填并次日重讲。</p><p><strong>W3 过关</strong>：构建优化 + 性能案例 + SSR 取舍能讲；精简算法约 6 题稳定；模拟 ≥2 场且有回填。</p><hr><h2 id="上场验收清单" tabindex="-1">上场验收清单 <a class="header-anchor" href="#上场验收清单" aria-label="Permalink to &quot;上场验收清单&quot;">​</a></h2><h3 id="手写-8" tabindex="-1">手写 8 <a class="header-anchor" href="#手写-8" aria-label="Permalink to &quot;手写 8&quot;">​</a></h3><ul><li>[ ] <code>new</code></li><li>[ ] 简易 Promise</li><li>[ ] <code>call</code> / <code>apply</code> / <code>bind</code></li><li>[ ] 防抖</li><li>[ ] 节流</li><li>[ ] 深拷贝</li><li>[ ] EventBus</li><li>[ ] <code>instanceof</code></li></ul><h3 id="口述-12" tabindex="-1">口述 12 <a class="header-anchor" href="#口述-12" aria-label="Permalink to &quot;口述 12&quot;">​</a></h3><ul><li>[ ] 闭包 / this</li><li>[ ] 事件循环</li><li>[ ] 渲染流水线</li><li>[ ] HTTP 缓存</li><li>[ ] Vue 响应式</li><li>[ ] Vue Diff / nextTick</li><li>[ ] React Hooks</li><li>[ ] Fiber / 双缓存</li><li>[ ] 合成事件</li><li>[ ] Vue vs React</li><li>[ ] Webpack 优化</li><li>[ ] SSR 取舍</li></ul><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><ul><li>[ ] 算法精简包约 6 题稳定（数组 / 树 / 链表）</li><li>[ ] 模拟面 ≥2 场录音，Top5 卡点已回填并重讲</li></ul><hr><h2 id="刻意不做" tabindex="-1">刻意不做 <a class="header-anchor" href="#刻意不做" aria-label="Permalink to &quot;刻意不做&quot;">​</a></h2><ul><li>不以 AI / Node / 小程序 / Hybrid 为主线</li><li>不追新题类型；以本仓库已有笔记为圆心</li><li>不把算法做成主战场（双框架已占时间）</li></ul>',38)])])}const f=e(i,[["render",h]]);export{u as __pageData,f as default};
